 return (Get-FileHash $path -Algorithm SHA256).Hash.ToLowerInvariant()
}
if($Action -eq 'build'){
 if(Test-Path $build){throw 'Build exists'}
 $spec.executable='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
 $spec.arguments=@('-NoLogo','-NoProfile','-NonInteractive','-File',(Join-Path $repo 'scripts\baiying_build_whole_provider.ps1'),'-OutDir',$build,'-DppReduction','1','-CompactNormalize','1','-HawkeyeReplayLanes','4','-CompileTimeoutSeconds','240','-ProjectionSafetyTest');$timeout=270
